// Package catalog holds the generated, embedded provider price catalog:
// the file format (design provider-price-catalog.md §4), the strict loader
// and its validation. It knows nothing about pricing.Rates: the compile
// from a loaded entry into a table row lives in package pricing, which
// imports this one (design D5, plan Task 2's layering rule).
//
// The file is generated by internal/pricing/catalog/gencatalog through
// scripts/gen-price-catalog.sh. Nothing here reads the network.
package catalog

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"maps"
	"slices"
	"sort"
	"strconv"
	"strings"
	"time"
)

// Version is the only file version this package understands. A file with
// any other version is refused at load, never read partially.
const Version = 1

// StaleAfter is how old a catalog's checked_at may be before the run stops
// trusting its cheap bound. It is the catalog's own threshold, shorter than
// the embedded Claude table's 90 days (internal/cli/budget.go): a
// marketplace price moves for reasons an age check cannot see, and a stale
// catalog charges the selected tier's maximum rather than refusing the run
// (design D10, P7). One number, so budget prices, doctor and the run all
// mean the same thing by "stale".
const StaleAfter = 30 * 24 * time.Hour

// maxPrice is the largest price the file may carry, in the file's own unit
// (US dollars per million tokens, or per 1,000 searches). It restates
// pricing.MaxPerM and pricing.MaxWebSearchPer1k, which are both 1000: this
// package must not import pricing, because pricing imports it.
const maxPrice = 1000

//go:embed catalog.json
var embedded []byte

// Load decodes the embedded catalog strictly and validates it. A malformed
// file is an error, never a partially applied table: the caller refuses the
// run rather than pricing from half a catalog.
func Load() (*File, error) { return Parse(embedded) }

// Parse decodes raw strictly and validates it: Load's body, exported for the
// generator, which must judge its own output by the reader's rules before it
// writes a file (a free endpoint's "0", a max below its min) rather than
// leaving it to fail in a test or, worse, in a released binary's Load.
func Parse(raw []byte) (*File, error) {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	var f File
	if err := dec.Decode(&f); err != nil {
		return nil, fmt.Errorf("the built-in price catalog is malformed: %w", err)
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return nil, errors.New("the built-in price catalog is malformed: trailing data after the JSON object")
	}
	if err := f.validate(); err != nil {
		return nil, fmt.Errorf("the built-in price catalog is malformed: %w", err)
	}
	return &f, nil
}

// validate is every rule the loader enforces. It is also what the
// generator's own test would catch first: the compile-time test
// (pricing.ApplyCatalog) makes a malformed shipped file unreachable in a
// released binary.
func (f *File) validate() error {
	var errs []error
	if f.Version != Version {
		errs = append(errs, fmt.Errorf("version is %d: this build reads version %d", f.Version, Version))
	}
	if _, err := time.Parse("2006-01-02", f.CheckedAt); err != nil {
		errs = append(errs, fmt.Errorf("checked_at %q is not YYYY-MM-DD", f.CheckedAt))
	}
	if len(f.Sources) == 0 {
		errs = append(errs, errors.New("sources is empty: the file must say what it was generated from"))
	}
	if len(f.Models) == 0 {
		errs = append(errs, errors.New("models is empty"))
	}
	canonical := map[string]string{} // canonical ID -> the row that claims it
	for _, id := range sortedIDs(f.Models) {
		e := f.Models[id]
		if e.CanonicalID != "" {
			// The row's key is a route's own ID and the canonical one is the
			// direct spelling of the same model, so a row may not claim its own
			// key, and two rows may not claim one canonical ID: two spellings of
			// one model are one model, and the price charged would depend on map
			// iteration order (plan Task 1b.2 step 1).
			switch prev, dup := canonical[e.CanonicalID]; {
			case e.CanonicalID == id:
				errs = append(errs, fmt.Errorf("%s: canonical_id is its own key: the canonical ID is the direct spelling (claude-sonnet-5-5) and the key is the route's (anthropic/claude-sonnet-5.5)", id))
			case strings.Contains(e.CanonicalID, "/"):
				// A canonical ID is the direct spelling a pin carries and the
				// price table keys, and that spelling carries no vendor
				// prefix: a value with one is another route's own ID, which
				// would pair a model with a second route and leave the map
				// (pricing's canonical-to-route table) with two answers to
				// where a call goes and what it costs. Refused here, at the
				// loader, so no shipped or generated row can say it.
				errs = append(errs, fmt.Errorf("%s: canonical_id %s is a route ID, not the canonical one: the canonical ID is the direct spelling (claude-sonnet-5-5), which carries no provider prefix", id, e.CanonicalID))
			case dup:
				errs = append(errs, fmt.Errorf("%s and %s both claim canonical_id %s: one canonical ID identifies one model", prev, id, e.CanonicalID))
			default:
				canonical[e.CanonicalID] = id
			}
		}
		if e.Endpoints <= 0 {
			errs = append(errs, fmt.Errorf("%s: endpoints is %d", id, e.Endpoints))
		}
		if e.ZDREndpoints < 0 || e.ZDREndpoints > e.Endpoints {
			errs = append(errs, fmt.Errorf("%s: zdr_endpoints is %d of %d endpoints", id, e.ZDREndpoints, e.Endpoints))
		}
		if (len(e.ZDR) > 0) != (e.ZDREndpoints > 0) {
			errs = append(errs, fmt.Errorf("%s: zdr_endpoints is %d but the zdr tier has %d dimensions", id, e.ZDREndpoints, len(e.ZDR)))
		}
		if len(e.All) == 0 {
			errs = append(errs, fmt.Errorf("%s: the all tier prices nothing", id))
		}
		for _, tier := range []struct {
			name string
			m    map[string]Bound
		}{{"all", e.All}, {"zdr", e.ZDR}} {
			// A dimension the six names do not cover is refused, never
			// folded: DisallowUnknownFields does not reach a map's keys,
			// so without this a misspelled "cache_read_per_m" would be
			// silently dropped and priced at the fold value (design D7's
			// whole point is that a dimension nobody priced is not a
			// dimension nobody charges).
			for _, d := range slices.Sorted(maps.Keys(tier.m)) {
				if !slices.Contains(Dimensions, d) {
					errs = append(errs, fmt.Errorf("%s %s: %q is not a price dimension (%s)", id, tier.name, d, strings.Join(Dimensions, ", ")))
				}
			}
			for _, d := range Dimensions {
				b, ok := tier.m[d]
				if !ok {
					continue
				}
				plain := true
				for _, x := range []struct{ name, s string }{{"min", b.Min}, {"max", b.Max}} {
					v, err := strconv.ParseFloat(x.s, 64)
					switch {
					case err != nil:
						errs = append(errs, fmt.Errorf("%s %s/%s.%s: %q is not a number", id, tier.name, d, x.name, x.s))
						plain = false
					case !plainDecimal(x.s):
						errs = append(errs, fmt.Errorf("%s %s/%s.%s: %q is not a plain decimal price (digits, optionally a point and digits): the max-below-min check compares the spellings, not floats, so an exponent like \"1e-5\" would be read as a different number than ParseFloat reads", id, tier.name, d, x.name, x.s))
						plain = false
					case !(v > 0) || v > maxPrice:
						errs = append(errs, fmt.Errorf("%s %s/%s.%s: %v is not more than 0 and at most %d", id, tier.name, d, x.name, v, maxPrice))
					}
				}
				if plain && less(b.Max, b.Min) {
					errs = append(errs, fmt.Errorf("%s %s/%s: max %s is below min %s", id, tier.name, d, b.Max, b.Min))
				}
				if b.MinOf == "" || b.MaxOf == "" {
					errs = append(errs, fmt.Errorf("%s %s/%s: min_of and max_of must name the endpoint at each extreme", id, tier.name, d))
				}
			}
		}
	}
	return errors.Join(errs...)
}

// plainDecimal reports whether s is a spelling the file may carry for a
// price: digits, optionally a point and more digits. Exponent spellings
// ("1e-5"), signs, a bare point and anything else are refused. less compares
// the spellings digit by digit, not the numbers, so a spelling it does not
// understand is a price the loader would check against the wrong neighbour
// while ParseFloat happily accepted it. Leading and trailing zeros stay
// accepted: they compare correctly and a diff may carry them.
func plainDecimal(s string) bool {
	whole, frac, point := strings.Cut(s, ".")
	if whole == "" || (point && (frac == "" || strings.Contains(frac, "."))) {
		return false
	}
	for _, part := range []string{whole, frac} {
		for _, r := range part {
			if r < '0' || r > '9' {
				return false
			}
		}
	}
	return true
}

// less compares two decimal price strings as numbers, without parsing them
// into a float: the file's numbers are decimal strings on purpose, and a
// comparison that rounded would let a max below its min through.
func less(a, b string) bool {
	ai, af, _ := strings.Cut(a, ".")
	bi, bf, _ := strings.Cut(b, ".")
	ai, bi = strings.TrimLeft(ai, "0"), strings.TrimLeft(bi, "0")
	if len(ai) != len(bi) {
		return len(ai) < len(bi)
	}
	if ai != bi {
		return ai < bi
	}
	n := max(len(af), len(bf))
	return af+strings.Repeat("0", n-len(af)) < bf+strings.Repeat("0", n-len(bf))
}

func sortedIDs(m map[string]Entry) []string {
	ids := make([]string, 0, len(m))
	for id := range m {
		ids = append(ids, id)
	}
	sort.Strings(ids)
	return ids
}

// File is the decoded catalog.json: the whole file, exactly as it is
// embedded. Every price is a decimal string in US dollars per million
// tokens (web search: per 1,000 searches), produced by an exact decimal
// shift of the API's per-token strings — never a float64 formatting.
type File struct {
	Version   int              `json:"version"`
	CheckedAt string           `json:"checked_at"` // YYYY-MM-DD
	Sources   []string         `json:"sources"`
	Models    map[string]Entry `json:"models"`
}

// Entry is one model's price ranges: a bound per dimension, per tier. The
// tiers are "zdr" (the endpoints with a zero-data-retention policy) and
// "all" (every endpoint the model is served by). A model with no
// ZDR-eligible endpoint has no ZDR tier at all (design D9): the key is
// absent, not empty, so a require_zdr route refuses the pin rather than
// pricing an empty set.
type Entry struct {
	// ContextTokens and MaxOutputTokens are the minimum over every
	// endpoint of the model (context_length, max_completion_tokens), so
	// nothing is reserved or allowed above what every endpoint accepts. 0
	// means the model reports none, and pricing's defaults apply.
	ContextTokens   int64 `json:"context_tokens"`
	MaxOutputTokens int64 `json:"max_output_tokens"`
	// Endpoints is the number of distinct endpoint tags the model is
	// served by; ZDREndpoints is how many of them are ZDR-eligible.
	Endpoints    int `json:"endpoints"`
	ZDREndpoints int `json:"zdr_endpoints"`
	// CanonicalID is the direct spelling of the same model — the Claude ID a
	// pin carries and the price table keys (claude-sonnet-5-5) — beside the
	// row's own key, which is the route's ID (anthropic/claude-sonnet-5.5).
	// The canonical-to-route map is pricing.ClaudeRoutes, checked in and
	// exhaustive; this field is the catalog's claim about the pair, and the
	// map is the authority on it (design §6.2, plan Task 1b.2). Empty on a row
	// whose key is not another spelling of a differently named model, which is
	// every non-Claude row.
	CanonicalID string `json:"canonical_id,omitempty"`
	// All is every endpoint; ZDR is the ZDR-eligible subset. Each maps a
	// dimension name (input_per_m, output_per_m, cache_read_per_m,
	// cache_write_5m_per_m, cache_write_1h_per_m, web_search_per_1k) to
	// its range. A dimension no endpoint of the tier prices is absent —
	// never written as 0 (design D7(a)).
	All map[string]Bound `json:"all"`
	ZDR map[string]Bound `json:"zdr,omitempty"`
}

// Bound is one dimension's range over a tier's endpoints: the per-dimension
// extremes, each naming the endpoint tag that holds it. Ties are broken by
// the lexicographically smallest tag, so the file cannot flap between runs.
type Bound struct {
	Min   string `json:"min"`
	Max   string `json:"max"`
	MinOf string `json:"min_of"`
	MaxOf string `json:"max_of"`
}

// Dimensions are the six the file expresses, in the order the file's
// reader and the generator both walk them. The five token dimensions are
// shifted six places from the API's per-token price; web_search_per_1k
// three.
var Dimensions = []string{
	"input_per_m", "output_per_m", "cache_read_per_m",
	"cache_write_5m_per_m", "cache_write_1h_per_m", "web_search_per_1k",
}
